import { randomUUID } from "node:crypto";
import { mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";

export interface Hotspot {
  id: string;
  title: string;
  selfTimeMs: number;
  percentOfTotal: number;
  summary: string;
  stack: string[];
  suggestedFix: string;
}

/** Token accounting for one agent run, summed across all assistant turns. */
export interface TokenUsage {
  /** Tokens sent to the model (excluding cache reads). */
  input: number;
  /** Tokens generated by the model. */
  output: number;
  /** Prompt tokens served from the provider's cache. */
  cacheRead: number;
  /** Tokens written into the provider's cache. */
  cacheWrite: number;
  /** Total tokens as reported by the provider. */
  totalTokens: number;
  /** USD cost reported by the provider (0 when the model has no known pricing). */
  costUsd: number;
}

export interface AnalysisRecord {
  id: string;
  createdAt: number;
  dir: string;
  totalMs: number;
  hasSourceMap: boolean;
  hotspots: Hotspot[];
  /** hotspotId -> generated fix prompt (cached after the second agent run). */
  prompts: Record<string, string>;
  /** Token usage of the analyzer agent run. */
  usage: TokenUsage;
  /** hotspotId -> token usage of the agent run that generated that prompt. */
  promptUsage: Record<string, TokenUsage>;
}

export const PROFILE_FILE_NAME = "profile.json";
export const SOURCEMAP_FILE_NAME = "sourcemap.json";
export const MAX_UPLOAD_BYTES = 25 * 1024 * 1024;

const MAX_HOTSPOTS = 12;
const MAX_STACK_FRAMES = 12;
const RECORD_TTL_MS = 60 * 60 * 1000;
const MAX_RECORDS = 24;

const records = new Map<string, AnalysisRecord>();

function baseDir(): string {
  return path.join(tmpdir(), "perf-ai-profiles");
}

export async function createAnalysisFiles(
  profile: File,
  sourceMap?: File
): Promise<{ id: string; dir: string; hasSourceMap: boolean }> {
  const id = randomUUID();
  const dir = path.join(baseDir(), id);
  await mkdir(dir, { recursive: true });
  await writeFile(path.join(dir, PROFILE_FILE_NAME), Buffer.from(await profile.arrayBuffer()));
  let hasSourceMap = false;
  if (sourceMap) {
    await writeFile(path.join(dir, SOURCEMAP_FILE_NAME), Buffer.from(await sourceMap.arrayBuffer()));
    hasSourceMap = true;
  }
  return { id, dir, hasSourceMap };
}

function pruneExpired(): void {
  const now = Date.now();
  for (const [id, record] of records) {
    if (now - record.createdAt > RECORD_TTL_MS) {
      void destroyRecord(id);
    }
  }
}

export function getRecord(id: string): AnalysisRecord | undefined {
  pruneExpired();
  return records.get(id);
}

export function putRecord(record: AnalysisRecord): void {
  pruneExpired();
  records.set(record.id, record);
  if (records.size > MAX_RECORDS) {
    const oldestFirst = [...records.values()].sort((a, b) => a.createdAt - b.createdAt);
    for (const record of oldestFirst.slice(0, records.size - MAX_RECORDS)) {
      void destroyRecord(record.id);
    }
  }
}

export async function destroyRecord(id: string, dir?: string): Promise<void> {
  const record = records.get(id);
  if (record) records.delete(id);
  const target = record?.dir ?? dir;
  if (!target) return;
  await rm(target, { recursive: true, force: true }).catch(() => undefined);
}

function slugify(value: string): string {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
}

function isRootLikeTitle(title: string): boolean {
  const normalized = title.trim();
  if (!normalized) return true;
  if (/^\(?\s*root\s*\)?$/i.test(normalized)) return true;
  if (/^\(all frames\)$/i.test(normalized)) return true;
  if (/^\(idle\)$/i.test(normalized)) return true;
  return false;
}

function asStringArray(value: unknown, max: number): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter((entry): entry is string => typeof entry === "string" && entry.trim().length > 0).slice(0, max);
}

/**
 * Validates the agent's raw report, drops the Root block and anything
 * unusable, recomputes percentages when needed and sorts by self time desc.
 */
export function normalizeHotspots(raw: unknown, totalMs: unknown): { hotspots: Hotspot[]; totalMs: number } {
  const validTotal = typeof totalMs === "number" && Number.isFinite(totalMs) && totalMs > 0 ? totalMs : 0;
  const list = Array.isArray(raw) ? raw : [];

  const hotspots: Hotspot[] = [];
  for (const entry of list) {
    if (!entry || typeof entry !== "object") continue;
    const candidate = entry as Record<string, unknown>;
    const title = typeof candidate.title === "string" ? candidate.title.trim() : "";
    const selfTimeMs = typeof candidate.selfTimeMs === "number" && Number.isFinite(candidate.selfTimeMs) ? candidate.selfTimeMs : NaN;
    if (!title || isRootLikeTitle(title) || !Number.isFinite(selfTimeMs) || selfTimeMs < 0) continue;

    const summary = typeof candidate.summary === "string" && candidate.summary.trim() ? candidate.summary.trim() : "No summary provided.";
    const suggestedFix = typeof candidate.suggestedFix === "string" && candidate.suggestedFix.trim() ? candidate.suggestedFix.trim() : "No fix suggested.";

    let percent = typeof candidate.percentOfTotal === "number" && Number.isFinite(candidate.percentOfTotal) ? candidate.percentOfTotal : 0;
    if (validTotal > 0) {
      // Authoritative: self time share of the total profile time.
      percent = (selfTimeMs / validTotal) * 100;
    } else if (percent <= 0) {
      percent = 0;
    }
    percent = Math.max(0, Math.min(100, percent));

    const rawId = typeof candidate.id === "string" && candidate.id.trim() ? candidate.id.trim() : title;
    hotspots.push({
      id: slugify(rawId) || `hotspot-${hotspots.length + 1}`,
      title: title.slice(0, 140),
      selfTimeMs,
      percentOfTotal: Math.round(percent * 100) / 100,
      summary,
      stack: asStringArray(candidate.stack, MAX_STACK_FRAMES),
      suggestedFix,
    });
  }

  hotspots.sort((a, b) => b.selfTimeMs - a.selfTimeMs);

  const seen = new Set<string>();
  const deduped = hotspots.filter((hotspot) => {
    if (seen.has(hotspot.id)) return false;
    seen.add(hotspot.id);
    return true;
  });

  return { hotspots: deduped.slice(0, MAX_HOTSPOTS), totalMs: validTotal };
}
